const face = (y = 104) => `<g fill="#584535"><circle cx="83" cy="${y}" r="4"/><circle cx="117" cy="${y}" r="4"/></g><path d="M94 ${y + 15}q6 7 12 0" fill="none" stroke="#584535" stroke-width="3" stroke-linecap="round"/>`;
export function drawing(kind, color = '#df976c', stage = 0) {
  const ears = `<circle cx="59" cy="63" r="25" fill="#b68a60"/><circle cx="141" cy="63" r="25" fill="#b68a60"/><circle cx="59" cy="63" r="13" fill="#e4bb8b"/><circle cx="141" cy="63" r="13" fill="#e4bb8b"/>`;
  switch (kind) {
    case 'circle': return `<circle cx="100" cy="100" r="66" fill="${color}"/><ellipse cx="79" cy="61" rx="19" ry="9" fill="#fff" opacity=".23" transform="rotate(-30 79 61)"/>${face(102)}`;
    case 'square': return `<rect x="38" y="38" width="124" height="124" rx="22" fill="${color}"/><path d="M57 66q0-9 9-9h31" fill="none" stroke="#fff" stroke-width="8" opacity=".23" stroke-linecap="round"/>${face(102)}`;
    case 'triangle': return `<path d="M87 33q13-22 26 0l65 116q12 23-14 23H36q-26 0-14-23Z" fill="${color}"/>${face(119)}`;
    case 'shapes': return `<g transform="translate(-14 53) scale(.65)">${drawing('circle','#df916c')}</g><g transform="translate(92 50) scale(.6)">${drawing('square','#7c9fbd')}</g><g transform="translate(49 -9) scale(.6)">${drawing('triangle','#dfbd62')}</g>`;
    case 'bear': return `${ears}<ellipse cx="100" cy="149" rx="53" ry="46" fill="#bc926b"/><ellipse cx="100" cy="160" rx="30" ry="27" fill="#e8caa4"/><circle cx="100" cy="99" r="60" fill="#c89e71"/><ellipse cx="100" cy="119" rx="26" ry="20" fill="#efcfaa"/><path d="M92 111q8-7 16 0l-8 8z" fill="#654d3b"/>${stage >= 3 ? '<path d="M78 97q7 7 14 0m16 0q7 7 14 0" fill="none" stroke="#654d3b" stroke-width="4" stroke-linecap="round"/>' : '<circle cx="82" cy="96" r="4" fill="#654d3b"/><circle cx="118" cy="96" r="4" fill="#654d3b"/>'}<path d="M93 125q7 7 14 0" fill="none" stroke="#654d3b" stroke-width="3" stroke-linecap="round"/>${stage === 1 ? '<circle cx="73" cy="122" r="5" fill="#ae6b43"/><circle cx="126" cy="130" r="4" fill="#ae6b43"/>' : ''}${stage >= 3 ? drawing('blanket') : ''}`;
    case 'cat': return `<path d="M43 82 39 24 84 51m32 0 44-27-3 60" fill="#dcad72"/><path d="m49 62-2-22 20 16m67 0 18-16-1 25" fill="#df9390"/><ellipse cx="100" cy="109" rx="69" ry="64" fill="#e9bb80"/><path d="m87 51 5 20m18-20-4 20" stroke="#c78d4d" stroke-width="6" stroke-linecap="round"/>${face()}<path d="m95 117 5 5 5-5" fill="#a76d62"/><path d="m37 116 29 6m-28 10 29-3m67-7 29-6m-28 13 28 3" stroke="#b6885b" stroke-width="3" stroke-linecap="round"/>`;
    case 'dog': return `<ellipse cx="100" cy="105" rx="61" ry="64" fill="#d9b184"/><ellipse cx="44" cy="91" rx="24" ry="48" fill="#986e51" transform="rotate(13 44 91)"/><ellipse cx="156" cy="91" rx="24" ry="48" fill="#986e51" transform="rotate(-13 156 91)"/><ellipse cx="100" cy="126" rx="28" ry="22" fill="#efd6b3"/>${face()}<ellipse cx="100" cy="116" rx="10" ry="7" fill="#67513f"/><path d="M95 139v7q5 11 10 0v-7" fill="#d98a83"/>`;
    case 'duck': return `<ellipse cx="106" cy="137" rx="65" ry="44" fill="#efd073"/><circle cx="88" cy="75" r="43" fill="#f4d779"/><path d="M57 81Q12 78 23 98l40 5" fill="#de9961"/><circle cx="73" cy="68" r="4" fill="#67503e"/><path d="M101 124q45-13 32 22-22 25-44 3" fill="#e3bd5c"/><path d="m152 110 29-19-7 40" fill="#efd073"/>`;
    case 'cow': return `<path d="M64 52 61 22 84 48m36 0 20-26-4 30" fill="#d6b472"/><ellipse cx="43" cy="73" rx="25" ry="14" fill="#a8a29a" transform="rotate(27 43 73)"/><ellipse cx="157" cy="73" rx="25" ry="14" fill="#a8a29a" transform="rotate(-27 157 73)"/><rect x="48" y="43" width="104" height="116" rx="42" fill="#fff8ec"/><path d="M49 88q0-48 36-44 21 11 4 37-13 23-40 7" fill="#756b5e"/><ellipse cx="100" cy="141" rx="56" ry="31" fill="#e6b3a6"/><circle cx="79" cy="142" r="5" fill="#9d776e"/><circle cx="121" cy="142" r="5" fill="#9d776e"/><circle cx="80" cy="94" r="4" fill="#423b33"/><circle cx="122" cy="94" r="4" fill="#423b33"/>`;
    case 'basket': return `<circle cx="73" cy="84" r="28" fill="#df8175"/><circle cx="126" cy="76" r="28" fill="#759cbc"/><path d="M34 98h132l-17 71H51Z" fill="${color}"/><rect x="27" y="89" width="146" height="18" rx="8" fill="${color}"/><path d="m62 116 7 37m31-37v37m38-37-7 37M54 130h94" stroke="#fff" opacity=".28" stroke-width="5"/>`;
    case 'box': return `<g transform="translate(35 -5) scale(.65)">${drawing('bear')}</g><path d="M35 91h130v85H35Z" fill="#cda779"/><path d="M100 91v85" stroke="#b99265" stroke-width="4"/><path d="m35 91-15 23 73 7 7-30m65 0 15 23-73 7-7-30" fill="#e8c796"/><path d="M74 151h52" stroke="#aa8052" stroke-width="4" stroke-linecap="round"/>`;
    case 'food': return `<ellipse cx="100" cy="153" rx="80" ry="24" fill="#dcded1"/><circle cx="100" cy="100" r="54" fill="#dba564"/><path d="M83 54q-23 22-23 46" stroke="#efc792" stroke-width="6" fill="none" stroke-linecap="round"/>${[[83,82],[123,94],[96,124],[74,112],[110,68]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="6" fill="#8c6143"/>`).join('')}`;
    case 'cloth': return `<rect x="36" y="40" width="128" height="124" rx="18" fill="#91babb"/><path d="M49 136h102m-102 12h102" stroke="#d9e8df" stroke-width="6"/><path d="m129 41 35 34h-22q-13 0-13-12" fill="#c6ddcf"/>`;
    case 'blanket': return `<path d="M33 145q67-28 134 0v44H33Z" fill="#819eb6"/><path d="M36 148q64-24 128 0" fill="none" stroke="#b5ccda" stroke-width="10"/><g fill="#e8dfb2"><path d="m72 159 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/><path d="m125 162 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/></g>`;
    case 'watering': return `<path d="m143 90 31-40 12 9-29 65" fill="#84a7bb"/><path d="M53 79C3 42 1 140 52 118" fill="none" stroke="#84a7bb" stroke-width="14"/><rect x="44" y="70" width="110" height="99" rx="25" fill="#98baca"/><ellipse cx="99" cy="74" rx="52" ry="13" fill="#7598ae"/><path d="M76 116h46m-23-23v46" stroke="#e2e9db" stroke-width="9" stroke-linecap="round"/>`;
    case 'flower': return `<path d="M100 164V85" stroke="#769164" stroke-width="9" stroke-linecap="round"/><path d="M98 142q-53 4-50-32 39-4 50 32m4-15q45 0 42-28-33-2-42 28" fill="#8ba76f"/><g fill="#e6b968">${[0,60,120,180,240,300].map(a=>`<ellipse cx="100" cy="49" rx="21" ry="29" transform="rotate(${a} 100 79)"/>`).join('')}</g><circle cx="100" cy="79" r="29" fill="#f9e5a3"/><g transform="translate(26 26) scale(.74)">${face(69)}</g><path d="M61 162h78l-10 31H71Z" fill="#c58f70"/><rect x="55" y="154" width="90" height="15" rx="6" fill="#d5a283"/>`;
    case 'drum': return `<path d="M36 86v70c0 27 128 27 128 0V86" fill="#d68876"/><path d="m42 99 22 53 24-44 25 44 25-48 20 48" stroke="#f9dfaf" stroke-width="5" fill="none"/><ellipse cx="100" cy="85" rx="64" ry="25" fill="#f6dbad" stroke="#b97a65" stroke-width="6"/><path d="m53 29 46 42m48-42-41 41" stroke="#907254" stroke-width="8" stroke-linecap="round"/><circle cx="51" cy="27" r="12" fill="#be9c76"/><circle cx="149" cy="27" r="12" fill="#be9c76"/>`;
    case 'bell': return `<path d="M61 141c-25 0-15-20-8-24l8-44q4-37 39-37t39 37l8 44c7 4 17 24-8 24Z" fill="#e1b85e"/><path d="M73 75q0-23 18-25" stroke="#f8dc8c" stroke-width="8" fill="none" stroke-linecap="round"/><circle cx="100" cy="152" r="16" fill="#bd9141"/><path d="M92 28q8-14 16 0" stroke="#bd9141" fill="none" stroke-width="8"/>`;
    case 'piano': return `<rect x="29" y="55" width="142" height="108" rx="18" fill="#817b9a"/>${[0,1,2,3,4].map((i)=>`<rect x="${39+i*25}" y="84" width="22" height="66" rx="4" fill="#fff7df"/>`).join('')}${[0,1,3].map(i=>`<rect x="${54+i*25}" y="84" width="15" height="37" rx="3" fill="#625971"/>`).join('')}<circle cx="49" cy="70" r="4" fill="#d5c09a"/>`;
    case 'car': return `<rect width="200" height="200" fill="#e4efe8"/><circle cx="164" cy="33" r="19" fill="#efcd74"/><path d="M0 138q43-29 95 0t105-5v67H0" fill="#c4d4b4"/><path d="M0 174h200" stroke="#a9b999" stroke-width="6"/><path d="m47 111 20-42q4-9 15-9h39q11 0 17 11l21 40" fill="#d98969"/><path d="m73 76-12 31h31V74H79q-4 0-6 2m33-2v33h35l-16-30q-2-3-8-3" fill="#f6edd4"/><rect x="30" y="105" width="143" height="49" rx="17" fill="#df9878"/><circle cx="63" cy="151" r="22" fill="#5f6863"/><circle cx="63" cy="151" r="10" fill="#e4d1ad"/><circle cx="142" cy="151" r="22" fill="#5f6863"/><circle cx="142" cy="151" r="10" fill="#e4d1ad"/><rect x="154" y="118" width="16" height="10" rx="4" fill="#f8dda0"/>`;
    default: return drawing('flower');
  }
}
export const art = (kind, color, stage, extra = '') => `<svg viewBox="0 0 200 200" aria-hidden="true" class="illustration" ${extra}>${drawing(kind, color, stage)}</svg>`;
export function puzzleArt(index, count) {
  const columns = 2, rows = count / 2;
  return `<svg viewBox="${(index % columns) * 100} ${Math.floor(index / columns) * (200 / rows)} 100 ${200 / rows}" aria-hidden="true" class="puzzle-image">${drawing('car')}</svg>`;
}
